const transitionRun = `-- name: TransitionRun :one
UPDATE procurement.agent_runs
SET status = $1,
    failure_reason = $2,
    started_at = CASE WHEN $1::text = 'RUNNING' THEN $3::timestamptz ELSE started_at END,
    completed_at = CASE WHEN $4::boolean THEN $3::timestamptz ELSE completed_at END,
    updated_at = $3::timestamptz
WHERE id = $5 AND status = ANY($6::text[])
RETURNING id, buyer_id, request_id, conversation_id, interrupt_id, candidate_set_id, run_type, status, failure_reason, result_revision_id, last_event_seq, min_available_seq, client_request_id, job_id, quota_period_start, created_at, started_at, completed_at, updated_at
`

type TransitionRunParams struct {
	ToStatus      string
	FailureReason *string
	Now           time.Time
	Terminal      bool
	ID            uuid.UUID
	FromStatuses  []string
}

func (q *Queries) TransitionRun(ctx context.Context, arg TransitionRunParams) (ProcurementAgentRun, error) {
	row := q.db.QueryRow(ctx, transitionRun,
		arg.ToStatus,
		arg.FailureReason,
		arg.Now,
		arg.Terminal,
		arg.ID,
		arg.FromStatuses,
	)
	var i ProcurementAgentRun
	err := row.Scan(
		&i.ID,
		&i.BuyerID,
		&i.RequestID,
		&i.ConversationID,
		&i.InterruptID,
		&i.CandidateSetID,
		&i.RunType,
		&i.Status,
		&i.FailureReason,
		&i.ResultRevisionID,
		&i.LastEventSeq,
		&i.MinAvailableSeq,
		&i.ClientRequestID,
		&i.JobID,
		&i.QuotaPeriodStart,
		&i.CreatedAt,
		&i.StartedAt,
		&i.CompletedAt,
		&i.UpdatedAt,
	)
	return i, err
}
